/**
 * HunterForge data pipeline.
 *
 * Reads the raw mhdb snapshots in data-raw/ (downloaded from https://wilds.mhdb.io,
 * a game-file-extracted Monster Hunter Wilds database by LartTyler — see
 * https://github.com/LartTyler/mhdb-wilds) and emits the typed datasets the site
 * imports from src/data/.
 *
 * Rerun with: npm run data:fetch && npm run data:generate
 * (data:fetch re-downloads snapshots; see scripts/fetch-data.mjs)
 *
 * DO NOT hand-edit generated files — change this script instead.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(fileURLToPath(new URL('.', import.meta.url)), '..');
const RAW = path.join(ROOT, 'data-raw');
const OUT = path.join(ROOT, 'src', 'data');
const SNAPSHOT_DATE = '2026-10-11';

const read = (f) => JSON.parse(fs.readFileSync(path.join(RAW, f), 'utf8'));
const write = (file, banner, body) => {
  const content = `${banner}\n${body}\n`;
  fs.writeFileSync(path.join(OUT, file), content, 'utf8');
  const kb = (Buffer.byteLength(content, 'utf8') / 1024).toFixed(1);
  console.log(`wrote src/data/${file} (${kb} kB)`);
};

const banner = (source) => `// AUTO-GENERATED by scripts/generate-data.mjs on ${SNAPSHOT_DATE} — DO NOT EDIT BY HAND.
// ${source}
// Rebuild: npm run data:fetch && npm run data:generate`;

function assert(cond, msg) {
  if (!cond) throw new Error(`DATA VALIDATION FAILED: ${msg}`);
}

// ---------------------------------------------------------------------------
// 1. Skills
// ---------------------------------------------------------------------------
const skillsRaw = read('skills.json');
const skillKindById = new Map(skillsRaw.map((s) => [s.id, s.kind]));
const skills = skillsRaw.map((s) => ({
  id: s.id,
  name: s.name,
  kind: s.kind, // 'armor' | 'weapon' | 'set' | 'group'
  maxLevel: s.ranks.length,
  levels: s.ranks.map((r) => r.description ?? ''),
}));
const skillNameToId = new Map(skillsRaw.map((s) => [s.name, s.id]));
const validKinds = new Set(['armor', 'weapon', 'set', 'group']);
for (const s of skills) {
  assert(validKinds.has(s.kind), `skill ${s.name} has unknown kind ${s.kind}`);
  assert(s.maxLevel >= 1 && s.maxLevel <= 7, `skill ${s.name} maxLevel ${s.maxLevel} out of range`);
}

write(
  'skills.ts',
  banner(`Source: https://wilds.mhdb.io/en/skills (extracted from game files), snapshot ${SNAPSHOT_DATE}.`),
  `import type { Skill } from './types';

/** All skills known to the game data snapshot (armor, weapon, set and group kinds). */
export const skills: Skill[] = ${JSON.stringify(skills)};`
);

// ---------------------------------------------------------------------------
// 2. High-rank armor pieces (all of them — 5 kinds x many sets/variants)
// ---------------------------------------------------------------------------
const armorRaw = read('armor.json');
const hrArmor = armorRaw.filter((p) => p.rank === 'high');
assert(hrArmor.length > 400, `expected a large HR dataset, got ${hrArmor.length}`);

const pieceKinds = new Set(['head', 'chest', 'arms', 'waist', 'legs']);
const armor = hrArmor.map((p) => {
  assert(pieceKinds.has(p.kind), `piece ${p.name} has unknown kind ${p.kind}`);
  for (const s of p.skills) {
    assert(skillNameToId.has(s.skill.name), `piece ${p.name} references unknown skill ${s.skill.name}`);
    assert(s.level >= 1, `piece ${p.name} skill ${s.skill.name} has level ${s.level}`);
  }
  for (const sl of p.slots ?? []) assert(sl >= 1 && sl <= 3, `piece ${p.name} has invalid slot level ${sl}`);
  // The game data lists set-bonus and group skills on every piece as inactive
  // tags. They are NOT active skills — they only fire at piece thresholds —
  // so keep them out of per-piece aggregation (handled via sets.ts instead).
  const activeSkills = p.skills.filter((s) => skillKindById.get(s.skill.id) === 'armor');
  return {
    id: p.id,
    name: p.name,
    kind: p.kind,
    rarity: p.rarity,
    setName: p.armorSet.name,
    defenseBase: p.defense.base,
    defenseMax: p.defense.max,
    resistances: p.resistances,
    slots: (p.slots ?? []).slice().sort((a, b) => b - a),
    skills: activeSkills.map((s) => ({ skillId: s.skill.id, name: s.skill.name, level: s.level })),
  };
});
assert(new Set(armor.map((a) => a.kind)).size === 5, 'HR dataset must cover all 5 piece kinds');

// Crafting materials ship as a separate chunk: the builder lazy-loads it only
// when a shopping list is rendered, keeping the initial payload small.
const armorCrafting = Object.fromEntries(
  hrArmor.map((p) => [p.id, (p.crafting?.materials ?? []).map((m) => ({ name: m.item.name, quantity: m.quantity }))])
);

write(
  'armor.ts',
  banner(`Source: https://wilds.mhdb.io/en/armor (extracted from game files), snapshot ${SNAPSHOT_DATE}.
// Scope: ALL high-rank armor pieces. Low-rank pieces are intentionally excluded.`),
  `import type { ArmorPiece } from './types';

/** Every high-rank armor piece in the snapshot. */
export const armorPieces: ArmorPiece[] = ${JSON.stringify(armor)};`
);

write(
  'armor-crafting.ts',
  banner(`Source: https://wilds.mhdb.io/en/armor (crafting materials), snapshot ${SNAPSHOT_DATE}.
// Lazy-loaded by the builder; keep it separate from armor.ts for payload size.`),
  `import type { MaterialCost } from './types';

/** pieceId -> crafting materials. */
export const armorCrafting: Record<number, MaterialCost[]> = ${JSON.stringify(armorCrafting)};`
);

// ---------------------------------------------------------------------------
// 3. Armor set bonuses + piece -> set family index
// ---------------------------------------------------------------------------
const setsRaw = read('armor_sets.json');

// Variant set names look like "Rey Dau α" / "Rey Dau β" / "Rey Dau γ" (low-rank
// entries have no suffix). The in-game set/group bonuses count pieces of the
// same monster family regardless of variant, so we group on the stripped name.
const familyOf = (variantName) => variantName.replace(/\s+[αβγ]$/, '').trim();

/** Set bonuses keyed by identity (skill + thresholds). Most monster families
 *  share one bonus across their α/β/γ variants (mixing variants counts towards
 *  the 2/4-piece thresholds); a few title-update sets (e.g. Gogmazios) give
 *  each variant a different bonus — pooling by identity handles both. */
const setBonusByKey = {};
/** groupSkillName -> granted skill. Group skills pool by NAME across sets
 *  (e.g. "Fortifying Pelt" appears on multiple families' α variants), so the
 *  activation count is over all equipped pieces carrying that group skill. */
const groupSkills = {};
/** pieceId -> { family, variant, groupSkillName?, setBonusKey? } */
const pieceSetIndex = {};

for (const set of setsRaw) {
  const family = familyOf(set.name);
  for (const p of set.pieces) pieceSetIndex[p.id] = { family, variant: set.name };
  if (set.setBonusSkill) {
    assert(skillNameToId.has(set.setBonusSkill.name), `set ${set.name} references unknown bonus skill`);
    const ranks = (set.bonus?.ranks ?? []).map((r) => ({
      pieces: r.pieces,
      level: r.skill.level,
      rankName: r.skill.name,
      description: r.skill.description ?? '',
    }));
    for (const r of ranks) {
      assert(r.pieces >= 2 && r.pieces <= 4, `set ${set.name} bonus threshold ${r.pieces} out of range`);
    }
    const key = `${set.setBonusSkill.id}:${ranks.map((r) => `${r.pieces}-${r.level}`).join(',')}`;
    if (!setBonusByKey[key]) {
      setBonusByKey[key] = {
        key,
        skillId: set.setBonusSkill.id,
        skillName: set.setBonusSkill.name,
        ranks,
        families: [],
      };
    }
    setBonusByKey[key].families.push(set.name);
    for (const p of set.pieces) pieceSetIndex[p.id].setBonusKey = key;
  }
  if (set.groupBonusSkill) {
    const firstRank = set.groupBonus?.ranks?.[0];
    const name = set.groupBonusSkill.name;
    const entry = {
      groupSkillName: name,
      grantedSkillName: firstRank?.skill?.name ?? name,
      grantedSkillId: firstRank?.skill?.skill?.id ?? set.groupBonusSkill.id,
      pieces: firstRank?.pieces ?? 3,
      level: firstRank?.skill?.level ?? 1,
      description: firstRank?.skill?.description ?? '',
    };
    // tag this variant's pieces with their group skill
    for (const p of set.pieces) pieceSetIndex[p.id].groupSkillName = name;
    const prev = groupSkills[name];
    if (prev) {
      assert(prev.grantedSkillName === entry.grantedSkillName, `group skill ${name} grants different skills in different sets`);
    } else {
      groupSkills[name] = entry;
    }
  }
}

// Every HR piece must resolve to a set family (used for bonus aggregation).
for (const p of armor) {
  assert(pieceSetIndex[p.id], `HR piece ${p.name} (${p.id}) missing from armor set index`);
}

write(
  'sets.ts',
  banner(`Source: https://wilds.mhdb.io/en/armor/sets (extracted from game files), snapshot ${SNAPSHOT_DATE}.
// Two bonus systems, modelled as the game does:
//  - Set bonuses (e.g. "Rey Dau's Voltage") fire at 2 and 4 pieces. Pieces pool
//    by bonus identity: variants sharing a bonus count together (the common
//    case); variant-specific bonuses (e.g. Gogmazios α vs β) count separately.
//  - Group skills (e.g. "Fortifying Pelt") pool by NAME across different sets:
//    any 3 equipped pieces carrying the same group skill activate it.`),
  `import type { SetBonus, GroupSkill, PieceSetMembership } from './types';

/** 2/4-piece set bonuses, pooled by identity (skill + thresholds). */
export const setBonuses: SetBonus[] = ${JSON.stringify(Object.values(setBonusByKey))};

/** Group skills: 3 pieces sharing the same group skill name -> granted skill. */
export const groupSkills: GroupSkill[] = ${JSON.stringify(Object.values(groupSkills))};

/** pieceId -> set family, variant name, group skill and set bonus it feeds. */
export const pieceSetIndex: Record<number, PieceSetMembership> = ${JSON.stringify(pieceSetIndex)};`
);

// ---------------------------------------------------------------------------
// 4. Decorations (armor-kind and weapon-kind)
// ---------------------------------------------------------------------------
const decosRaw = read('decorations.json');
const decorations = decosRaw.map((d) => {
  assert(d.slot >= 1 && d.slot <= 3, `deco ${d.name} invalid slot ${d.slot}`);
  assert(d.kind === 'armor' || d.kind === 'weapon', `deco ${d.name} unknown kind ${d.kind}`);
  for (const s of d.skills) {
    assert(skillNameToId.has(s.skill.name), `deco ${d.name} references unknown skill ${s.skill.name}`);
    assert(s.level >= 1, `deco ${d.name} skill level ${s.level}`);
  }
  return {
    id: d.id,
    name: d.name,
    slot: d.slot,
    rarity: d.rarity,
    kind: d.kind,
    skills: d.skills.map((s) => ({ skillId: s.skill.id, name: s.skill.name, level: s.level })),
  };
});

write(
  'decorations.ts',
  banner(`Source: https://wilds.mhdb.io/en/decorations (extracted from game files), snapshot ${SNAPSHOT_DATE}.
// NOTE: the upstream API does not expose decoration crafting materials — flagged in the UI.`),
  `import type { Decoration } from './types';

/** All decorations. kind 'armor' fits armor slots; kind 'weapon' fits weapon slots. */
export const decorations: Decoration[] = ${JSON.stringify(decorations)};`
);

// ---------------------------------------------------------------------------
// 5. Charms (Wilds' talisman slot: fixed skills, no slots)
// ---------------------------------------------------------------------------
const charmsRaw = read('charms.json');
const charms = [];
for (const family of charmsRaw) {
  for (const r of family.ranks) {
    for (const s of r.skills) {
      assert(skillNameToId.has(s.skill.name), `charm ${r.name} references unknown skill ${s.skill.name}`);
    }
    charms.push({
      id: r.id,
      name: r.name,
      level: r.level,
      rarity: r.rarity,
      skills: r.skills.map((s) => ({ skillId: s.skill.id, name: s.skill.name, level: s.level })),
      craftable: r.crafting?.craftable ?? false,
      materials: (r.crafting?.materials ?? []).map((m) => ({ name: m.item.name, quantity: m.quantity })),
    });
  }
}

write(
  'charms.ts',
  banner(`Source: https://wilds.mhdb.io/en/charms (extracted from game files), snapshot ${SNAPSHOT_DATE}.`),
  `import type { Charm } from './types';

/** Charm ranks (the talisman slot). Charms in Wilds carry fixed skills and no decoration slots. */
export const charms: Charm[] = ${JSON.stringify(charms)};`
);

// ---------------------------------------------------------------------------
// 6. Weapon presets for the ERaw calculator (one notable max-rarity weapon per kind)
// ---------------------------------------------------------------------------
const weaponsRaw = read('weapons.json');
const kindBest = new Map();
for (const w of weaponsRaw) {
  const prev = kindBest.get(w.kind);
  const better =
    !prev ||
    w.rarity > prev.rarity ||
    (w.rarity === prev.rarity && w.damage.raw > prev.damage.raw) ||
    (w.rarity === prev.rarity && w.damage.raw === prev.damage.raw && w.name < prev.name);
  if (better) kindBest.set(w.kind, w);
}
const weaponPresets = [...kindBest.values()]
  .sort((a, b) => a.kind.localeCompare(b.kind))
  .map((w) => ({
    id: w.id,
    name: w.name,
    kind: w.kind,
    rarity: w.rarity,
    raw: w.damage.raw,
    affinity: w.affinity ?? 0,
    slots: w.slots ?? [],
  }));
assert(weaponPresets.length === 14, `expected 14 weapon kinds, got ${weaponPresets.length}`);

write(
  'weapons.ts',
  banner(`Source: https://wilds.mhdb.io/en/weapons (extracted from game files), snapshot ${SNAPSHOT_DATE}.
// Curated: highest-rarity, highest-raw weapon of each of the 14 kinds — presets only, not a full weapon DB.`),
  `import type { WeaponPreset } from './types';

/** One notable endgame weapon per kind, used as ERaw calculator presets. */
export const weaponPresets: WeaponPreset[] = ${JSON.stringify(weaponPresets)};`
);

// ---------------------------------------------------------------------------
// 7. Meta / coverage snapshot (counts are computed, prose is curated here)
// ---------------------------------------------------------------------------
const armorSkillsGranted = new Set(armor.flatMap((p) => p.skills.map((s) => s.skillId)));
const charmSkillsGranted = new Set(charms.flatMap((c) => c.skills.map((s) => s.skillId)));
const armorDecoSkills = new Set(decorations.filter((d) => d.kind === 'armor').flatMap((d) => d.skills.map((s) => s.skillId)));

const meta = {
  snapshotDate: SNAPSHOT_DATE,
  gameVersionNote: 'Title-update era game data as served by wilds.mhdb.io on the snapshot date.',
  coverage: {
    highRankArmorPieces: armor.length,
    armorSets: Object.keys(setBonusByKey).length,
    armorSetsTotal: setsRaw.length,
    skillsTotal: skills.length,
    skillsGrantedByArmor: armorSkillsGranted.size,
    skillsGrantedByCharms: charmSkillsGranted.size,
    skillsGrantedByArmorDecos: armorDecoSkills.size,
    decorations: decorations.length,
    armorDecorations: decorations.filter((d) => d.kind === 'armor').length,
    weaponDecorations: decorations.filter((d) => d.kind === 'weapon').length,
    charmRanks: charms.length,
    weaponPresets: weaponPresets.length,
  },
};

write(
  'meta.ts',
  banner('Coverage counts are computed from the generated datasets; edit prose in scripts/generate-data.mjs.'),
  `import type { SiteMeta } from './types';

/** Snapshot metadata: what the dataset covers, when it was taken, and where it came from. */
export const meta: SiteMeta = ${JSON.stringify(meta, null, 2)};`
);

console.log('\nData generation complete.');
console.log(`  HR armor pieces: ${armor.length} (with slots: ${armor.filter((a) => a.slots.length).length})`);
console.log(`  Sets with bonuses: ${Object.keys(setBonusByKey).length} of ${setsRaw.length} | group skills: ${Object.keys(groupSkills).length}`);
console.log(`  Skills: ${skills.length} | Decos: ${decorations.length} (${decorations.filter((d) => d.kind === 'armor').length} armor / ${decorations.filter((d) => d.kind === 'weapon').length} weapon) | Charms: ${charms.length}`);
